async function api(path:string,data?:unknown,method='POST') {
 const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),60000);
 try{const r=await fetch(path,{...(data?{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{}),signal:controller.signal});if(r.status===401)throw new Error('Your session expired. Reload to sign in; pending game drafts will be recovered.');const raw=await r.text();let b:any;try{b=JSON.parse(raw);}catch{throw new Error(r.status>=500||r.status===404?'The server is restarting or unreachable. Wait a few seconds and try again; your game is kept on this device.':'The server sent an unexpected reply. Reload and try again.');}if(!r.ok)throw new Error(b.error||'The request failed.');return b;}
 catch(e){if(e instanceof TypeError||controller.signal.aborted)throw new Error('Cannot connect to Chessito. Pending game drafts stay on this device; reconnect and retry.');throw e;}finally{clearTimeout(timeout);}
}

function monthLabel(m:string){const [y,mo]=m.split('.');return new Date(Number(y),Number(mo)-1,1).toLocaleDateString(undefined,{month:'long',year:'numeric'});}
function dateLabel(g:GameRecord){if(g.gameDate&&/^\d{4}\.\d{2}\.\d{2}$/.test(g.gameDate)){const [y,m,d]=g.gameDate.split('.').map(Number);return new Date(y,m-1,d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}return new Date(g.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}
function download(text:string,name:string,type='application/x-chess-pgn'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function score(e:Evaluation|null){if(!e)return '—';if(e.mate!==undefined)return e.mate===0?'Mate':`M${e.mate}`;return `${e.cp>=0?'+':''}${(e.cp/100).toFixed(1)}`;}
function resultLabel(g:GameRecord){if(g.outcome)return {won:'Won',lost:'Lost',drawn:'Draw',unfinished:g.source==='imported'?'Unfinished':'In progress',other:g.result}[g.outcome];return g.result==='*'?(g.source==='imported'?'Unfinished':'In progress'):g.result==='1/2-1/2'?'Draw':(g.result==='1-0')===(g.color==='w')?'Won':'Lost';}
const timeControls:{label:string;tc:{base:number;inc:number}|null}[]=[{label:'Untimed',tc:null},{label:'1 min',tc:{base:60,inc:0}},{label:'3 min',tc:{base:180,inc:0}},{label:'3 | 2',tc:{base:180,inc:2}},{label:'5 min',tc:{base:300,inc:0}},{label:'10 min',tc:{base:600,inc:0}},{label:'15 | 10',tc:{base:900,inc:10}},{label:'30 min',tc:{base:1800,inc:0}}];
function fmtClock(ms:number){const t=Math.max(0,ms);if(t<10000)return `0:0${(t/1000).toFixed(1)}`;const s=Math.ceil(t/1000);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
