 const [nativeEngines,setNativeEngines]=useState<NativeEngine[]>([]);const [engineServiceError,setEngineServiceError]=useState('');
 const [engineStatus,setEngineStatus]=useState('Loading engine');const [busy,setBusy]=useState('');const [aiBusy,setAiBusy]=useState(false);const [saveStatus,setSaveStatus]=useState('Private & synced');
 const [notice,setNotice]=useState('');const [error,setError]=useState('');const [selected,setSelected]=useState<Square|null>(null);const [flipped,setFlipped]=useState(false);const [showNew,setShowNew]=useState(false);const [bot,setBot]=useState(0);const [customElo,setCustomElo]=useState(1500);const [botTab,setBotTab]=useState<'ladder'|'style'|'odds'|'custom'>('ladder');const [engineChoice,setEngineChoice]=useState('stockfish');const [color,setColor]=useState<'w'|'b'>('w');
 const [startingPosition,setStartingPosition]=useState<{fen:string;title:string;goal:string;color:'w'|'b'}|null>(null);
 const [ply,setPly]=useState(0);const [currentEval,setCurrentEval]=useState<Evaluation|null>(null);const [feedback,setFeedback]=useState<ReviewMove|null>(null);const [aiText,setAiText]=useState('');const [hint,setHint]=useState('');const [pgn,setPgn]=useState('');const [search,setSearch]=useState('');const [promotion,setPromotion]=useState<{from:string;to:string}|null>(null);const [confirm,setConfirm]=useState<'resign'|string|null>(null);const [reviewProgress,setReviewProgress]=useState({done:0,total:0});
 const [showOver,setShowOver]=useState(false);
