 const pendingPrefix=()=>`chessito-pending:${uidRef.current||'unknown'}:`;const pendingKey=(id:string)=>pendingPrefix()+id;
 const ownDraft=(k:string)=>k.startsWith(pendingPrefix())||(uidRef.current==='docker-owner'&&k.startsWith('chessito-pending:')&&!k.slice(17).includes(':'));
 const [opponentFilter,setOpponentFilter]=useState('');const [outcomeFilter,setOutcomeFilter]=useState('');const [monthFilter,setMonthFilter]=useState('');const [orderFilter,setOrderFilter]=useState('');const [months,setMonths]=useState<{month:string;count:number}[]>([]);const [outcomeCounts,setOutcomeCounts]=useState<Record<string,number>>({});
